"kind": "propose",
"summary": "The new revision's liveness probe is too strict for startup; increasing the initial delay allows the app to start before being probed.",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "The liveness probe kills the container before it starts listening, as indicated by the event message and pod state.",
    "supporting": ["ev-target_events", "ev-pod_states", "ev-rollout_history", "ev-container_logs_tail"],
