    "root_cause_class": "new_version_broken",
    "summary": "The failure started after the rollout, and the previous revision ran without issues.",
    "supporting": ["failure_onset_after_rollout", "earlier_revision_healthy", "failures_came_with_rollout"],
    "contradicting": [],
