"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 90
    }
  },
  "expected_effect": "The liveness probe will wait longer before checking, allowing the application to start and bind before being probed.",
  "rationale": "The logs show the app takes ~60s to load routes, but the liveness probe checks every 10s starting at 10s. The event explicitly states the probe kills the container before it listens. Raising the initial delay to 90s matches the suggested fix in the event, giving the app time to start without premature termination.",
  "cited_evidence_ids": ["ev-target_events", "ev-pod_states", "ev-rollout_history", "ev-container_logs_tail"],
  "cited_predicates": ["failure_onset_after_rollout", "earlier_revision_healthy", "failures_came_with_rollout", "killed_during_startup", "probe_kills"]
}
}
